mapper.select:
select a.attachment_id as "attachmentId", a.notice_id as "noticeId", a.original_file_name as "originalFileName", a.file_content as "fileContent" from notice_attachments a join notices n on n.notice_id = a.notice_id where a.notice_id = #{noticeId} and a.attachment_id = #{attachmentId} and n.status = 'ACTIVE' and CURRENT_DATE between n.publish_start_date and n.publish_end_date and exists ( select 1 from notice_targets role_target where role_target.notice_id = n.notice_id and role_target.target_type = 'ROLE' and role_target.target_id in
#{roleCode}
)
and exists ( with recursive ancestors(organization_code) as ( select #{organizationCode} union all select rel.parent_organization_code from organization_relations rel join ancestors a2 on a2.organization_code = rel.organization_code where rel.status = 'ACTIVE' and (rel.effective_end_date is null or rel.effective_end_date >= CURRENT_DATE) ) select 1 from notice_targets org_target join ancestors anc on anc.organization_code = org_target.target_id where org_target.notice_id = n.notice_id and org_target.target_type = 'ORGANIZATION' )
